@page "/apply"
@using sv_424d1f7dc4d042708e0f2f838e06b58e.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <div class="d-flex justify-content-between mb-4 position-relative step-indicator">
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var step = i + 1;
            var label = StepLabels[i];
            var isCurrent = step == CurrentStep;
            var isCompleted = step < CurrentStep;
            var isFuture = step > CurrentStep;
            var clickable = isCompleted && !IsSubmitted;

            <div class="text-center flex-fill step-item @(isCurrent ? "step-current" : "") @(isCompleted ? "step-completed" : "") @(isFuture ? "step-future" : "")"
                 role="button"
                 @onclick="() => { if (clickable) GoToStep(step); }"
                 style="cursor: @(clickable ? "pointer" : "default")">
                <div class="step-circle mx-auto mb-1 @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <small class="@(isFuture ? "text-muted" : "")">@label</small>
            </div>
        }
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @* ───── Step 1: Personal Info ───── *@
    @if (CurrentStep == 1)
    {
        <div class="card">
            <div class="card-header"><h5 class="mb-0">Personal Information</h5></div>
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="FullName" placeholder="John Doe" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="Email" placeholder="john@example.com" />
                    @if (!string.IsNullOrEmpty(EmailError))
                    {
                        <div class="text-danger mt-1"><small>@EmailError</small></div>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="Phone" placeholder="(555) 123-4567" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Address <span class="text-danger">*</span></label>
                    <textarea class="form-control" @bind="Address" rows="2" placeholder="123 Main St, City, State ZIP"></textarea>
                </div>
                <div class="d-flex justify-content-end">
                    <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@IsValidating">
                        @if (IsValidating)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Next &raquo;
                    </button>
                </div>
            </div>
        </div>
    }

    @* ───── Step 2: Work History ───── *@
    @if (CurrentStep == 2)
    {
        <div class="card">
            <div class="card-header"><h5 class="mb-0">Work History</h5></div>
            <div class="card-body">
                @for (int i = 0; i < WorkEntries.Count; i++)
                {
                    var index = i;
                    var entry = WorkEntries[index];
                    <div class="border rounded p-3 mb-3 position-relative">
