                                       @onchange="e => UpdateWorkEntry(index, entry with { Company = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Title"
                                       @onchange="e => UpdateWorkEntry(index, entry with { Title = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                        <div class="row mb-3">
