        ErrorMessage = null;
        EmailError = null;
        CurrentStep = step;
    }

    // ───── Step 1 Validation ─────

    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        CurrentStep = 2;
    }

    // ───── Step 2 ─────

    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryForm());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, WorkEntryForm updated) => WorkEntries[index] = updated;

    private void NextFromWorkHistory()
    {
        ErrorMessage = null;
        foreach (var entry in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == default)
            {
                ErrorMessage = "Please fill in the company, title, and start date for each position.";
                return;
            }
        }
        CurrentStep = 3;
    }

    // ───── Step 3 ─────

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceForm());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm updated) => References[index] = updated;

    private void NextFromReferences()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }
        CurrentStep = 4;
    }

    // ───── Step 4 ─────

    private void NextFromCoverLetter()
    {
        ErrorMessage = null;
        if (CoverLetter.Length > 2000)
        {
            ErrorMessage = "Cover letter must be 2000 characters or fewer.";
            return;
        }
        CurrentStep = 5;
    }

    // ───── Step 5 ─────

    private async Task SubmitApplication()
    {
        IsSubmitting = true;
        ErrorMessage = null;

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(
                WorkEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList());
            var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, refs, CoverLetter);

            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }

    // ───── Form Models ─────

    private record WorkEntryForm
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private record ReferenceForm
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}
