@page "/apply"
@using sv_424d1f7dc4d042708e0f2f838e06b58e.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <div class="d-flex justify-content-between mb-4 position-relative step-indicator">
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var step = i + 1;
            var label = StepLabels[i];
            var isCurrent = step == CurrentStep;
            var isCompleted = step < CurrentStep;
            var isFuture = step > CurrentStep;
            var clickable = isCompleted && !IsSubmitted;

            <div class="text-center flex-fill step-item @(isCurrent ? "step-current" : "") @(isCompleted ? "step-completed" : "") @(isFuture ? "step-future" : "")"
                 role="button"
                 @onclick="() => { if (clickable) GoToStep(step); }"
                 style="cursor: @(clickable ? "pointer" : "default")">
                <div class="step-circle mx-auto mb-1 @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <small class="@(isFuture ? "text-muted" : "")">@label</small>
            </div>
        }
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @* ───── Step 1: Personal Info ───── *@
    @if (CurrentStep == 1)
    {
        <div class="card">
            <div class="card-header"><h5 class="mb-0">Personal Information</h5></div>
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="FullName" placeholder="John Doe" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="Email" placeholder="john@example.com" />
                    @if (!string.IsNullOrEmpty(EmailError))
                    {
                        <div class="text-danger mt-1"><small>@EmailError</small></div>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="Phone" placeholder="(555) 123-4567" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Address <span class="text-danger">*</span></label>
                    <textarea class="form-control" @bind="Address" rows="2" placeholder="123 Main St, City, State ZIP"></textarea>
                </div>
                <div class="d-flex justify-content-end">
                    <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@IsValidating">
                        @if (IsValidating)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Next &raquo;
                    </button>
                </div>
            </div>
        </div>
    }

    @* ───── Step 2: Work History ───── *@
    @if (CurrentStep == 2)
    {
        <div class="card">
            <div class="card-header"><h5 class="mb-0">Work History</h5></div>
            <div class="card-body">
                @for (int i = 0; i < WorkEntries.Count; i++)
                {
                    var index = i;
                    var entry = WorkEntries[index];
                    <div class="border rounded p-3 mb-3 position-relative">
                        <h6 class="mb-3">Position @(index + 1)</h6>
                        @if (WorkEntries.Count > 1)
                        {
                            <button class="btn btn-sm btn-outline-danger position-absolute top-0 end-0 m-2"
                                    @onclick="() => RemoveWorkEntry(index)">Remove</button>
                        }
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Company"
                                       @onchange="e => UpdateWorkEntry(index, entry with { Company = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Title"
                                       @onchange="e => UpdateWorkEntry(index, entry with { Title = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" value="@(entry.StartDate == default ? "" : entry.StartDate.ToString("yyyy-MM-dd"))"
                                       @onchange="e => UpdateWorkEntry(index, entry with { StartDate = DateTime.TryParse((string?)e.Value, out var d) ? d : default })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" value="@(entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                                       disabled="@entry.IsCurrent"
                                       @onchange="e => UpdateWorkEntry(index, entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end">
                                <div class="form-check mb-2">
                                    <input class="form-check-input" type="checkbox" checked="@entry.IsCurrent"
                                           @onchange="e => UpdateWorkEntry(index, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
                                    <label class="form-check-label">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-2">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="2" value="@entry.Description"
                                      @onchange="e => UpdateWorkEntry(index, entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
                        </div>
                    </div>
                }
                <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">
                    + Add Another Position
                </button>
                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="() => GoToStep(1)">&laquo; Back</button>
                    <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next &raquo;</button>
                </div>
            </div>
        </div>
    }

    @* ───── Step 3: References ───── *@
    @if (CurrentStep == 3)
    {
        <div class="card">
            <div class="card-header"><h5 class="mb-0">References</h5></div>
            <div class="card-body">
                @for (int i = 0; i < References.Count; i++)
                {
                    var index = i;
                    var refEntry = References[index];
                    <div class="border rounded p-3 mb-3 position-relative">
                        <h6 class="mb-3">Reference @(index + 1)</h6>
                        @if (References.Count > 2)
                        {
                            <button class="btn btn-sm btn-outline-danger position-absolute top-0 end-0 m-2"
                                    @onclick="() => RemoveReference(index)">Remove</button>
                        }
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Name"
                                       @onchange="e => UpdateReference(index, refEntry with { Name = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Relationship"
                                       @onchange="e => UpdateReference(index, refEntry with { Relationship = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                        <div class="row mb-3">
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" value="@refEntry.Email"
                                       @onchange="e => UpdateReference(index, refEntry with { Email = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" value="@refEntry.Phone"
                                       @onchange="e => UpdateReference(index, refEntry with { Phone = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                    </div>
                }
                @if (References.Count < 3)
                {
                    <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
                        + Add Reference
                    </button>
                }
                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="() => GoToStep(2)">&laquo; Back</button>
                    <button class="btn btn-primary" @onclick="NextFromReferences">Next &raquo;</button>
                </div>
            </div>
        </div>
    }

    @* ───── Step 4: Cover Letter ───── *@
    @if (CurrentStep == 4)
    {
        <div class="card">
            <div class="card-header"><h5 class="mb-0">Cover Letter</h5></div>
            <div class="card-body">
                <div class="mb-2">
                    <textarea class="form-control" rows="10" @bind="CoverLetter" placeholder="Tell us why you're a great fit for this position..."></textarea>
                </div>
                <div class="text-muted mb-3">
                    <small>@CoverLetter.Length / 2000 characters</small>
                </div>
                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="() => GoToStep(3)">&laquo; Back</button>
                    <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next &raquo;</button>
                </div>
            </div>
        </div>
    }

    @* ───── Step 5: Review & Submit ───── *@
    @if (CurrentStep == 5)
    {
        @if (IsSubmitted)
        {
            <div class="card border-success">
                <div class="card-body text-center py-5">
                    <div class="text-success mb-3" style="font-size:3rem;">&#10003;</div>
                    <h4 class="text-success">Application Submitted Successfully!</h4>
                    <p class="lead">Your application ID is <strong>#@SubmittedApplicationId</strong></p>
                    <p class="text-muted">Thank you for applying. We will review your application and get back to you.</p>
                </div>
            </div>
        }
        else
        {
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Personal Information</h5>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                <div class="card-body">
                    <div class="row">
                        <div class="col-md-6"><strong>Full Name:</strong> @FullName</div>
                        <div class="col-md-6"><strong>Email:</strong> @Email</div>
                        <div class="col-md-6 mt-2"><strong>Phone:</strong> @Phone</div>
                        <div class="col-md-6 mt-2"><strong>Address:</strong> @Address</div>
                    </div>
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Work History</h5>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var entry in WorkEntries)
                    {
                        <div class="mb-3 pb-3 border-bottom">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <small class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </small>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mt-1 mb-0">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">References</h5>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var r in References)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> (@r.Relationship)<br />
                            <small>@r.Email &bull; @r.Phone</small>
                        </div>
                    }
                </div>
            </div>

            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">Cover Letter</h5>
                    <button class="btn btn-sm btn-link" @onclick="() => GoToStep(4)">Edit</button>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;">@CoverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="() => GoToStep(4)">&laquo; Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsSubmitting">
                    @if (IsSubmitting)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Submit Application
                </button>
            </div>
        }
    }
</div>

@code {
    private static readonly string[] StepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; } = 1;

    // Step 1
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;
    private string? EmailError { get; set; }
    private bool IsValidating { get; set; }

    // Step 2
    private List<WorkEntryForm> WorkEntries { get; set; } = new() { new() };

    // Step 3
    private List<ReferenceForm> References { get; set; } = new() { new(), new() };

    // Step 4
    private string CoverLetter { get; set; } = string.Empty;

    // Step 5
    private bool IsSubmitting { get; set; }
    private bool IsSubmitted { get; set; }
    private int SubmittedApplicationId { get; set; }

    private string? ErrorMessage { get; set; }

    // ───── Navigation ─────

    private void GoToStep(int step)
    {
        ErrorMessage = null;
        EmailError = null;
        CurrentStep = step;
    }

    // ───── Step 1 Validation ─────

    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        CurrentStep = 2;
    }

    // ───── Step 2 ─────

    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryForm());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, WorkEntryForm updated) => WorkEntries[index] = updated;

    private void NextFromWorkHistory()
    {
        ErrorMessage = null;
        foreach (var entry in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == default)
            {
                ErrorMessage = "Please fill in the company, title, and start date for each position.";
                return;
            }
        }
        CurrentStep = 3;
    }

    // ───── Step 3 ─────

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceForm());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm updated) => References[index] = updated;

    private void NextFromReferences()
    {
        ErrorMessage = null;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }
        CurrentStep = 4;
    }

    // ───── Step 4 ─────

    private void NextFromCoverLetter()
    {
        ErrorMessage = null;
        if (CoverLetter.Length > 2000)
        {
            ErrorMessage = "Cover letter must be 2000 characters or fewer.";
            return;
        }
        CurrentStep = 5;
    }

    // ───── Step 5 ─────

    private async Task SubmitApplication()
    {
        IsSubmitting = true;
        ErrorMessage = null;

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(
                WorkEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList());
            var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, refs, CoverLetter);

            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }

    // ───── Form Models ─────

    private record WorkEntryForm
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private record ReferenceForm
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

